function resolveBookToken(token){const t=norm(token);for(const [alias,id] of aliases)if(t===alias)return{id,match:'exact',alias};const lead=t.match(/^([123])(.*)$/),wantNum=lead?.[1]||null;let best=null,second=null;for(const [alias,id] of aliases){const aLead=alias.match(/^([123])(.*)$/);if(wantNum&&aLead?.[1]&&aLead[1]!==wantNum)continue;const d=editDistance(t,alias),limit=Math.max(1,Math.min(3,Math.floor(Math.max(t.length,alias.length)*.2)));if(d>limit)continue;const score=d/Math.max(t.length,alias.length);const item={id,alias,d,score};if(!best||score<best.score||(score===best.score&&d<best.d)){second=best;best=item}else if(!second||score<second.score)second=item}if(best&&(!second||best.id===second.id||second.score-best.score>=.035))return{id:best.id,match:'fuzzy',alias:best.alias,distance:best.d};return null}
