function applyDesign(){pushHistory();const theme=$('#designTheme').value,t=THEMES[theme];project.ratio=$('#designRatio').value;project.master.theme=theme;project.master.bg=$('#designBgText').value||t.bg;project.master.accent=$('#designAccentText').value||t.accent;project.master.fg=t.fg;project.master.titleFont=$('#designTitleFont').value;project.master.bodyFont=$('#designBodyFont').value;for(const s of project.slides)for(const e of s.elements){if(e.type==='text'&&e.bold)e.fontFamily=project.master.titleFont;else if(['text','bible'].includes(e.type))e.fontFamily=project.master.bodyFont;if(['text','bible'].includes(e.type)&&(!e.color||['#fff','#ffffff','#f8fbf9','#17231c'].includes(e.color.toLowerCase())))e.color=project.master.fg}renderAll();scheduleSave();closeDlg('designDlg')}
/* presenter */
function presentRole(e,s,index){if(e.role)return e.role;if(e.type==='bible')return'bible';if(['Title','Section'].includes(s.name))return'title';if(s.name==='Bible'){const texts=s.elements.filter(x=>x.type==='text');if(e.id===texts[0]?.id)return'bibleRef';if(e.id===texts[1]?.id)return'bibleText'}if(s.name==='Text'&&index===0&&s.elements.length>1)return'subtitle';return'body'}
function roleFontRange(role,stageW){const k=stageW/1920;const map={title:[72,128],subtitle:[42,74],bibleRef:[38,60],bibleText:[58,96],bible:[56,90],body:[50,82]};const [min,max]=map[role]||map.body;return[Math.max(22,min*k),Math.max(30,max*k)]}
function fitPresentNode(node,e,role){if(!['text','bible'].includes(e.type))return;const stage=$('#presentCanvas'),range=roleFontRange(role,stage.clientWidth),min=range[0]*presentTextScale,max=range[1]*presentTextScale;const authored=Math.max(1,+e.fontSize||36)*stage.clientWidth/960*presentTextScale;let hi=Math.max(min,Math.min(max,Math.max(authored,min))),lo=Math.min(min,hi);node.style.fontSize=hi+'px';const fits=()=>node.scrollHeight<=node.clientHeight+2&&node.scrollWidth<=node.clientWidth+2;if(fits())return;for(let i=0;i<12;i++){const mid=(lo+hi)/2;node.style.fontSize=mid+'px';if(fits())lo=mid;else hi=mid}node.style.fontSize=Math.max(18,lo)+'px'}
function showPresentControls(){const p=$('#presenter');p.classList.add('controlsVisible');clearTimeout(presentControlsTimer);presentControlsTimer=setTimeout(()=>p.classList.remove('controlsVisible'),2600)}
function setPresentScale(v){presentTextScale=Math.max(.7,Math.min(1.5,Math.round(v*20)/20));$('#presentScaleLabel').textContent=Math.round(presentTextScale*100)+'%';renderPresent();showPresentControls()}
function renderPresent(){const s=project.slides[presentIndex],stage=$('#presentCanvas'),theme=slideTheme();stage.classList.toggle('ratio43',project.ratio==='4:3');stage.style.background=theme.bg;stage.style.setProperty('--verse-number-color',verseNumberColor(theme.bg));stage.innerHTML=s.elements.sort((a,b)=>(a.z||1)-(b.z||1)).map(e=>`<div class="presentEl" data-present-id="${e.id}" data-type="${e.type}"><div class="content">${elementInner(e)}</div></div>`).join('');stage.querySelectorAll('.presentEl').forEach(n=>{const e=s.elements.find(x=>x.id===n.dataset.presentId);applyElStyle(n,e,stage);fitElementToBox(n,e,stage);if(presentTextScale!==1){const c=n.querySelector('.content'),px=parseFloat(c.style.fontSize)||0;c.style.fontSize=(px*presentTextScale)+'px'}});$('#presentCounter').textContent=`${presentIndex+1} / ${project.slides.length}`;$('#presentBlack').classList.toggle('hidden',!presentBlack)}
function startPresent(){if(!project)return;presentIndex=Math.max(0,project.slides.findIndex(s=>s.id===slideId));presentBlack=false;presentTextScale=1;presentFsStarted=false;$('#presentScaleLabel').textContent='100%';const presenter=$('#presenter');presenter.classList.remove('hidden');renderPresent();showPresentControls();const req=presenter.requestFullscreen?.({navigationUI:'hide'})||presenter.requestFullscreen?.();if(req?.then)req.then(()=>presentFsStarted=true).catch(()=>{})}
function stopPresent(){presentFsStarted=false;$('#presenter').classList.add('hidden');if(document.fullscreenElement)document.exitFullscreen?.().catch(()=>{})}
