/* pptx */
function cssHex(v,fallback='FFFFFF'){if(!v)return fallback;const s=String(v).trim();if(/^#[0-9a-f]{6}$/i.test(s))return s.slice(1);const m=s.match(/rgba?\((\d+)[, ]+(\d+)[, ]+(\d+)/i);return m?[+m[1],+m[2],+m[3]].map(n=>n.toString(16).padStart(2,'0')).join('').toUpperCase():fallback}
function pptxRichRuns(e,theme){if(!e.rich)return null;const root=document.createElement('div');root.innerHTML=sanitizeRichHTML(e.rich);const runs=[],base={color:(e.color||project.master.fg||theme.fg).replace('#',''),fontFace:fontBy(e.fontFamily).family,bold:!!e.bold,italic:!!e.italic},numColor=verseNumberColor(theme.bg).replace('#',''),sup=project.master.verseNumberStyle==='superscript';const walk=(n,opt={...base})=>{if(n.nodeType===3){if(n.nodeValue)runs.push({text:n.nodeValue,options:{...opt}});return}if(n.nodeType!==1)return;const o={...opt},tag=n.tagName;if(['B','STRONG'].includes(tag))o.bold=true;if(['I','EM'].includes(tag))o.italic=true;if(tag==='U')o.underline={color:o.color};if(tag==='FONT'){if(n.getAttribute('face'))o.fontFace=n.getAttribute('face');if(n.getAttribute('color'))o.color=cssHex(n.getAttribute('color'),o.color)}const st=n.style;if(st?.color)o.color=cssHex(st.color,o.color);if(st?.fontFamily)o.fontFace=st.fontFamily.replace(/["']/g,'').split(',')[0];if(st?.fontWeight&&(+st.fontWeight>=600||st.fontWeight==='bold'))o.bold=true;if(st?.fontStyle==='italic')o.italic=true;if(st?.backgroundColor)o.highlight=cssHex(st.backgroundColor,'FFE066');if(n.classList?.contains('verseNo')){o.bold=true;o.color=numColor;o.superscript=sup}if(tag==='BR'){runs.push({text:'',options:{...o,breakLine:true}});return}for(const c of n.childNodes)walk(c,o);if(['DIV','P'].includes(tag))runs.push({text:'',options:{...o,breakLine:true}})};for(const n of root.childNodes)walk(n);return runs}
function pptxBibleRuns(e,theme){const runs=[],bodyColor=(e.color||project.master.fg||theme.fg).replace('#',''),numColor=verseNumberColor(theme.bg).replace('#',''),sup=project.master.verseNumberStyle==='superscript';if(e.type==='bible'&&e.ref)runs.push({text:e.ref,options:{bold:true,color:(project.master.accent||theme.accent).replace('#',''),breakLine:true}});const lines=String(e.text||'').split(/\n+/).filter(Boolean);for(const line of lines){const m=line.match(/^\s*([០-៩0-9]+)\s+(.*)$/);if(m){runs.push({text:m[1],options:{bold:true,color:numColor,superscript:sup}});runs.push({text:' '+m[2],options:{color:bodyColor,breakLine:true}})}else runs.push({text:line,options:{color:bodyColor,breakLine:true}})}return runs}
function loadScript(src){return new Promise((res,rej)=>{if(window.PptxGenJS)return res();const s=document.createElement('script');s.src=src;s.onload=res;s.onerror=rej;document.head.append(s)})}
async function exportPptx(){if(!project)return;const btn=$('#exportBtn'),old=btn.textContent;btn.disabled=true;btn.textContent='Exporting…';try{if(!window.PptxGenJS)await loadScript('https://cdn.jsdelivr.net/gh/gitbrent/pptxgenjs@3.12.0/dist/pptxgen.bundle.js');const pptx=new PptxGenJS();pptx.layout=project.ratio==='4:3'?'LAYOUT_4X3':'LAYOUT_WIDE';pptx.author='Powerslide · Bible1954';pptx.title=project.title;const W=project.ratio==='4:3'?10:13.333,H=7.5,theme=slideTheme();for(const s of project.slides){const sl=pptx.addSlide();sl.background={color:(project.master.bg||theme.bg).replace('#','')};for(const e of s.elements.sort((a,b)=>(a.z||1)-(b.z||1))){const x=e.x/100*W,y=e.y/100*H,w=e.w/100*W,h=e.h/100*H;if(e.type==='shape'){sl.addShape(pptx.ShapeType.rect,{x,y,w,h,fill:{color:(e.fill||project.master.accent).replace('#',''),transparency:Math.round((1-(e.opacity??1))*100)},line:{color:(e.fill||project.master.accent).replace('#',''),transparency:100},radius:e.radius||0})}else if(e.type==='image'&&e.data){sl.addImage({data:e.data,x,y,w,h})}else{const isBible=e.type==='bible'||e.role==='bibleText',text=e.rich?(pptxRichRuns(e,theme)||e.text):(isBible?pptxBibleRuns(e,theme):(e.text||''));sl.addText(text,{x,y,w,h,fontFace:fontBy(e.fontFamily).family,fontSize:Math.max(8,(e.fontSize||32)*.75),bold:!!e.bold,italic:!!e.italic,color:(e.color||project.master.fg).replace('#',''),align:e.align||'left',valign:e.valign==='top'?'top':e.valign==='bottom'?'bottom':'mid',margin:0.02,breakLine:false,fit:'shrink',transparency:Math.round((1-(e.opacity??1))*100)})}}}await pptx.writeFile({fileName:`${project.date}-${project.title.replace(/[\\/:*?"<>|]/g,'-')}.pptx`});toast('PPTX រួចរាល់')}catch(e){console.error(e);alert('PPTX export ត្រូវការ Internet លើកដំបូងសម្រាប់ PPTX engine។ Browser presentation នៅតែប្រើ offline បាន។')}finally{btn.disabled=false;btn.textContent=old}}
